using System;using System.Collections.Generic;using System.IO;using System.Linq;using System.Reflection;using OwnLabView;
class RunInterfaceMethods {
 static Dictionary<string,object> Read(string p){return Data.Map(Data.Json.DeserializeObject(File.ReadAllText(p)));}
 [STAThread]static int Main(string[] a){typeof(Storage).GetField("Root").SetValue(null,a[0]);object app=null,project=null,context=null;var refs=new List<object>();var checks=new List<object>();string phase="attach";try{
 var prep=Read(Path.Combine(a[1],"prepared.json"));string child=Data.Text(prep,"vi_path"),root=Directory.GetFiles(Path.Combine(Path.GetDirectoryName(child),"p"),"*.lvclass").Single();var bundle=ClassSnapshot.Accepted(child);bundle.VerifySources();
 using(var lease=new NiSessionLease()){app=Activator.CreateInstance(Type.GetTypeFromProgID("LabVIEW.Application",true));lease.Attached();project=LabView.Invoke(app,"NewProject",BindingFlags.InvokeMethod);context=LabView.Invoke(project,"Application",BindingFlags.GetProperty);
 using(var n=new TypeImport.Session(context,refs,bundle)){
 object vi;string path;var expected=new Dictionary<string,object>();
 if(a[2]=="create"){
  phase="author caller";var g=new ClassGraph(n,Path.Combine(a[1],"DynamicFinite_"+Guid.NewGuid().ToString("N").Substring(0,8)+".vi"),a[1]);vi=g.VI;path=g.Path;int i=0;
  foreach(string cls in new[]{root,child}){uint obj=Convert.ToUInt32(n.Call("Native_AddConstantFromTypedef",ClassGraph.D("owner_diagram_id",g.Diagram,"typedef_path",cls,"x",(short)30,"y",(short)50),"terminal_id")["terminal_id"]);var pins=g.Pins(g.Sub(Directory.GetFiles(Path.GetDirectoryName(root),"Compute.vi",SearchOption.AllDirectories).Single()));g.Wire(obj,pins["self in"]);g.Control(pins["A"],"A"+i);g.Control(pins["B"],"B"+i);g.Indicator(pins["Sum"],"Result"+i);expected["Result"+i]=i==0?5.0:6.0;
   var second=g.Pins(g.Sub(Directory.GetFiles(Path.GetDirectoryName(root),"Compute.vi",SearchOption.AllDirectories).Single()));g.Wire(pins["self out"],second["self in"]);g.Control(second["A"],"AgainA"+i);g.Control(second["B"],"AgainB"+i);g.Indicator(second["Sum"],"Again"+i);expected["Again"+i]=i==0?6.5:-22.5;i++;
  }g.Save();Storage.WriteNew(Path.Combine(a[1],"interface-caller.json"),new{path,sha256=Data.Hash(path),expected});
 }else{var r=Read(Path.Combine(a[1],"interface-caller.json"));path=Data.Text(r,"path");if(Data.Hash(path)!=Data.Text(r,"sha256"))throw new IOException("Caller changed.");expected=Data.Map(r["expected"]);vi=n.Open(path);}
 phase="runtime";if(Convert.ToInt32(LabView.Invoke(vi,"ExecState",BindingFlags.GetProperty))!=1)throw new IOException("Caller is not executable.");for(int i=0;i<2;i++){LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"A"+i,2.0);LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"B"+i,3.0);LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"AgainA"+i,-2.5);LabView.Invoke(vi,"SetControlValue",BindingFlags.InvokeMethod,"AgainB"+i,9.0);}LabView.Invoke(vi,"Run",BindingFlags.InvokeMethod,false);
 foreach(var pair in expected){double actual=Convert.ToDouble(LabView.Invoke(vi,"GetControlValue",BindingFlags.InvokeMethod,pair.Key));if(actual!=Convert.ToDouble(pair.Value))throw new IOException("Dynamic result differs: "+pair.Key+"="+actual);checks.Add(new{label=pair.Key,value=actual,passed=true});}bundle.VerifySources();Storage.WriteNew(Path.Combine(a[1],"interface-runtime-"+a[2]+".json"),new{passed=true,checks,caller_path=path,source_files_unchanged=true,same_parent_method_used=true,window_operations_used=false});
 }}return 0;}catch(Exception e){Storage.WriteNew(Path.Combine(a[1],"interface-runtime-failure-"+a[2]+".json"),new{phase,error=e.ToString(),checks});return 1;}finally{for(int i=refs.Count-1;i>=0;i--)LabView.Release(refs[i]);if(project!=null)try{LabView.Invoke(project,"Close",BindingFlags.InvokeMethod);}catch{}LabView.Release(context);LabView.Release(project);LabView.Release(app);}}
}
